design_text:
{
  "site_summary": "A north-facing, full-shade balcony with moderate moisture and one cat resident.",
  "layout_strategy": "Hanging spider plants trail from upper wall hooks at eye level, architectural cast iron and parlor palms form an upright mid-layer against the back wall in containers, and low-growing creeping Charlie carpets the floor-level planters.",
  "combination_logic": "The scheme combines fine arching foliage with broad, glossy architectural leaves and cascading mats, creating a rich tapestry of green textures that thrives entirely without direct sunlight.",
  "zones": [
    {
      "zone_name": "Upper Canopy",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On north-facing wall hooks, full shade, zero direct sunlight and sheltered from wind.",
      "plants": [
        {
          "scientific_name": "Chlorophytum comosum",
          "common_name": "Spider Plant",
          "why": "Adapts exceptionally well to full shade and creates a wonderful cascading effect.",
          "role_in_combination": "Contributes bright variegated linear foliage that contrasts with the darker, solid greens below."
        }
      ],
      "maintenance": [
        "Water thoroughly when the top inch of soil feels dry",
        "Feed with a balanced liquid fertilizer monthly in spring and summer",
        "Remove any browned tips regularly"
      ]
    },
    {
      "zone_name": "Mid-Level Architecture",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "Against the back wall in large containers, full shade, no direct sun.",
      "plants": [
        {
          "scientific_name": "Aspidistra elatior",
          "common_name": "Cast Iron Plant",
          "why": "Nearly indestructible in low-light conditions and adds strong vertical presence.",
          "role_in_combination": "Provides bold, upright, dark green sword-like leaves that anchor the mid-layer."
        },
        {
          "scientific_name": "Chamaedorea elegans",
          "common_name": "Parlor Palm",
          "why": "Thrives in indirect, low-light environments and brings a delicate tropical texture.",
          "role_in_combination": "Offers fine, feathery fronds that contrast heavily with the broad leaves of the cast iron plant."
        }
      ],
      "maintenance": [
        "Water moderately, allowing the soil to dry slightly between waterings",
        "Wipe leaves with a damp cloth occasionally to remove dust",
        "Repot every two to three years in fresh potting mix"
      ]
    },
    {
      "zone_name": "Feline Grazing and Ground Edge",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "In low, accessible floor planters along the balcony edge, full shade.",
      "plants": [
        {
          "scientific_name": "Pilea nummulariifolia",
          "common_name": "Creeping Charlie",
          "why": "Forms a lush, dense carpet at ground level and is completely safe for cats.",
          "role_in_combination": "Acts as a soft green groundcover that unifies the base of the larger pots."
        }
      ],
      "maintenance": [
        "Keep the soil evenly moist but not waterlogged",
        "Trim back wandering stems lightly if they outgrow their boundaries",
        "Refresh topsoil annually with organic compost"
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture in all containers by inserting a finger two inches deep",
      "frequency": "Twice a week in summer, weekly in spring and autumn",
      "season": "Summer"
    },
    {
      "task": "Clean dust off broad foliage to maximize light absorption in low-light conditions",
      "frequency": "Monthly",
      "season": "Spring"
    },
    {
      "task": "Bring tender potted plants indoors or protect containers if severe freezing winter weather threatens",
      "frequency": "As needed during cold snaps",
      "season": "Winter"
    }
  ],
  "care_cautions": [
    "Overwatering the mid-level containers in full shade can easily lead to root rot since evaporation rates are very low.",
    "Ensure drainage holes in the floor planters remain unblocked so that the ground-level creeping Charlie does not sit in stagnant water."
  ],
  "pet_safety_note": "All selected plants are non-toxic and cat-safe, allowing the resident cat to safely explore and graze on the ground-level foliage all day long."
}
